    "id": "fr-lib-58-how-gps-works",
    "lang": "fr",
    "langLabel": "Français",
    "title": "Comment fonctionne le GPS",
    "source": "Generated explainer",
    "level": "B1",
    "topic": "how GPS works",
    "pairs": [
      {
        "target": "Le GPS est un système qui aide à connaître notre position exacte sur la Terre.",
        "en": "GPS is a system that helps to know our exact position on Earth."
      },
      {
        "target": "Il utilise plusieurs satellites placés dans l'espace qui envoient des signaux.",
        "en": "It uses several satellites placed in space that send signals."
      },
      {
        "target": "Un appareil GPS reçoit ces signaux et mesure le temps qu'ils mettent pour arriver.",
        "en": "A GPS device receives these signals and measures the time they take to arrive."
      },
      {
        "target": "En connaissant la vitesse des signaux, il peut calculer la distance de chaque satellite.",
        "en": "By knowing the speed of the signals, it can calculate the distance from each satellite."
      },
      {
        "target": "Avec la distance d'au moins quatre satellites, le GPS peut déterminer votre position précise.",
        "en": "With the distance from at least four satellites, GPS can determine your precise location."
      },
      {
        "target": "Cette technique s'appelle la triangulation ou plus précisément, la trilatération.",
        "en": "This technique is called triangulation or more precisely, trilateration."
      },
      {
        "target": "Grâce au GPS, nous pouvons utiliser des cartes numériques pour trouver des itinéraires.",
        "en": "Thanks to GPS, we can use digital maps to find routes."
      },
      {
        "target": "Le GPS est très utilisé dans les voitures, les téléphones et même pour la navigation maritime.",
        "en": "GPS is widely used in cars, phones, and even for maritime navigation."
      },
      {
        "target": "Ce système a été développé à l'origine pour des raisons militaires.",
        "en": "This system was originally developed for military purposes."
      },
      {
        "target": "Mais aujourd'hui, il est accessible à tout le monde pour de nombreuses applications.",
        "en": "But today, it is accessible to everyone for many applications."
      },
      {
        "target": "Pour fonctionner correctement, un appareil GPS a besoin d'un bon signal satellite.",
        "en": "To work properly, a GPS device needs a good satellite signal."
      },
      {
        "target": "Les grands bâtiments ou les forêts denses peuvent parfois bloquer ce signal.",
        "en": "Tall buildings or dense forests can sometimes block this signal."
      },
      {
        "target": "Il est important aussi que l'appareil ait une bonne batterie pour rester allumé.",
        "en": "It is also important that the device has a good battery to stay on."
      },
      {
        "target": "En résumé, le GPS rend la vie plus facile en nous guidant où que nous soyons.",
        "en": "In summary, GPS makes life easier by guiding us wherever we are."
      }
    ]
