    "id": "fr-lib-59-what-quantum-computing-is",
    "lang": "fr",
    "langLabel": "Français",
    "title": "L'informatique quantique expliquée",
    "source": "Generated explainer",
    "level": "B2",
    "topic": "what quantum computing is",
    "pairs": [
      {
        "target": "L'informatique quantique est une nouvelle façon de concevoir des ordinateurs.",
        "en": "Quantum computing is a new way of designing computers."
      },
      {
        "target": "Au lieu d'utiliser des bits classiques, elle utilise des qubits.",
        "en": "Instead of using classical bits, it uses qubits."
      },
      {
        "target": "Un qubit peut représenter 0, 1, ou une superposition des deux en même temps.",
        "en": "A qubit can represent 0, 1, or a superposition of both at the same time."
      },
      {
        "target": "Cela permet aux ordinateurs quantiques de traiter beaucoup plus d'informations simultanément.",
        "en": "This allows quantum computers to process much more information simultaneously."
      },
      {
        "target": "La superposition est une idée clé provenant de la physique quantique.",
        "en": "Superposition is a key idea coming from quantum physics."
      },
      {
        "target": "Les qubits sont aussi liés entre eux par un phénomène appelé intrication.",
        "en": "Qubits are also linked together by a phenomenon called entanglement."
      },
      {
        "target": "L'intrication permet aux qubits de rester connectés, même à distance.",
        "en": "Entanglement allows qubits to stay connected, even at a distance."
      },
      {
        "target": "Grâce à ces propriétés, certaines tâches peuvent être réalisées plus rapidement qu'avec un ordinateur classique.",
        "en": "Thanks to these properties, some tasks can be performed faster than with a classical computer."
      },
      {
        "target": "Par exemple, la recherche dans une grande base de données peut être accélérée.",
        "en": "For example, searching in a large database can be sped up."
      },
      {
        "target": "Cependant, construire un ordinateur quantique est très difficile.",
        "en": "However, building a quantum computer is very difficult."
      },
      {
        "target": "Il faut contrôler les qubits dans un environnement très froid et stable.",
        "en": "The qubits must be controlled in a very cold and stable environment."
      },
      {
        "target": "Les erreurs sont également un grand défi en informatique quantique.",
        "en": "Errors are also a big challenge in quantum computing."
      },
      {
        "target": "Les scientifiques travaillent encore pour rendre cette technologie plus fiable.",
        "en": "Scientists are still working to make this technology more reliable."
      },
      {
        "target": "Un jour, les ordinateurs quantiques pourraient révolutionner la science, la médecine et bien d'autres domaines.",
        "en": "One day, quantum computers could revolutionize science, medicine, and many other fields."
      }
    ]
