    "id": "fr-lib-68-the-placebo-effect",
    "lang": "fr",
    "langLabel": "Français",
    "title": "L'effet placebo expliqué",
    "source": "Generated explainer",
    "level": "B2",
    "topic": "the placebo effect",
    "pairs": [
      {
        "target": "L'effet placebo est un phénomène fascinant en psychologie et médecine.",
        "en": "The placebo effect is a fascinating phenomenon in psychology and medicine."
      },
      {
        "target": "Il se produit lorsque quelqu'un ressent une amélioration après avoir reçu un traitement sans principe actif.",
        "en": "It happens when someone feels better after receiving a treatment with no active ingredient."
      },
      {
        "target": "Par exemple, une personne peut prendre une pilule de sucre, croyant que c'est un médicament.",
        "en": "For example, a person might take a sugar pill, believing it is medicine."
      },
      {
        "target": "Si cette personne se sent mieux, on parle d'effet placebo.",
        "en": "If that person feels better, we call it the placebo effect."
      },
      {
        "target": "Ce mécanisme montre l'incroyable pouvoir de l'esprit sur le corps.",
        "en": "This mechanism shows the incredible power of the mind over the body."
      },
      {
        "target": "Des études montrent que les attentes positives peuvent déclencher des réactions chimiques dans le cerveau.",
        "en": "Studies show that positive expectations can trigger chemical reactions in the brain."
      },
      {
        "target": "Ces réactions aident à réduire la douleur ou d'autres symptômes.",
        "en": "These reactions help reduce pain or other symptoms."
      },
      {
        "target": "Les chercheurs utilisent souvent des placebos pour tester l'efficacité des nouveaux médicaments.",
        "en": "Researchers often use placebos to test the effectiveness of new medicines."
      },
      {
        "target": "Ils comparent les résultats entre un groupe qui reçoit le vrai médicament et un autre groupe placebo.",
        "en": "They compare the results between a group receiving the real medicine and another placebo group."
      },
      {
        "target": "Cela permet de voir si le médicament fonctionne au-delà de l'effet placebo.",
        "en": "This helps see if the medicine works beyond the placebo effect."
      },
      {
        "target": "Cependant, l'effet placebo ne remplace pas un traitement médical réel.",
        "en": "However, the placebo effect does not replace real medical treatment."
      },
      {
        "target": "Il s'agit plutôt d'un complément intéressant à la compréhension de la guérison.",
        "en": "It is rather an interesting complement to understanding healing."
      },
      {
        "target": "Beaucoup de patients ressentent un bénéfice grâce à l'effet placebo, surtout dans des cas de douleur chronique.",
        "en": "Many patients feel benefits thanks to the placebo effect, especially in cases of chronic pain."
      },
      {
        "target": "Cela prouve l'importance de l'attitude mentale dans la santé.",
        "en": "This proves the importance of mental attitude in health."
      }
    ]
